import pytest

if pytest.use_correct:
    from correct_python_programs.kth import kth
else:
    from python_programs.kth import kth


def test_attack_1():
    # pivot is minimum, forces recursion into `above` with offset 1
    arr = [1, 2, 3, 4, 5]
    expected = sorted(arr)
    for k in range(len(arr)):
        assert kth(list(arr), k) == expected[k]


def test_attack_2():
    # duplicate pivots + non-empty above: distinguishes k-num_lessoreq vs k-num_less
    # sorted = [1,5,5,7,8,9], k=3 must be 7, not 9
    arr = [5, 1, 5, 7, 8, 9]
    expected = sorted(arr)
    for k in range(len(arr)):
        assert kth(list(arr), k) == expected[k]


def test_attack_3():
    # larger duplicate run with larger above part, checks every above index
    arr = [4, 1, 2, 4, 4, 5, 6, 7, 8]
    expected = sorted(arr)
    for k in range(len(arr)):
        assert kth(list(arr), k) == expected[k]


def test_attack_4():
    # k == num_less boundary must return pivot, not recurse into below
    # pivot=3, below=[1,2], k=2 must be 3
    arr = [3, 3, 3, 1, 2]
    expected = sorted(arr)
    for k in range(len(arr)):
        assert kth(list(arr), k) == expected[k]
    assert kth(list(arr), 2) == 3


def test_attack_5():
    # k == num_lessoreq boundary must go to above, not return pivot
    # pivot=2, below=[1], above=[3,4], k=3 must be 3 not 2
    arr = [2, 3, 1, 2, 4]
    expected = sorted(arr)
    for k in range(len(arr)):
        assert kth(list(arr), k) == expected[k]
    assert kth(list(arr), 1) == 2
    assert kth(list(arr), 2) == 2
    assert kth(list(arr), 3) == 3


def test_attack_6():
    # negatives with duplicates, mixed pivot
    arr = [0, -1, 5, -1, 0, 3, -2, 5]
    expected = sorted(arr)
    for k in range(len(arr)):
        assert kth(list(arr), k) == expected[k]


def test_attack_7():
    # all-equal and single-element cases
    for arr in ([7, 7, 7, 7, 7], [42], [-5, -5, -5, 1, 2]):
        expected = sorted(arr)
        for k in range(len(arr)):
            assert kth(list(arr), k) == expected[k]

